def para(text='',align=None,keep=False):
    p=d.add_paragraph(text,'Normal')
    p.paragraph_format.keep_together=True
    p.paragraph_format.keep_with_next=keep
    if align is not None: p.alignment=align
    for r in p.runs: r.font.size=Pt(14); r.font.name='Times New Roman'
    return p

def heading(text,level=1,page=False):
    p=d.add_paragraph(text,f'Heading {level}')
    p.alignment=WD_ALIGN_PARAGRAPH.LEFT
    if page: p.paragraph_format.page_break_before=True
    # Explicit manual section numbering; disable inherited list numbering.
    np=OxmlElement('w:numPr'); ni=OxmlElement('w:numId'); ni.set(qn('w:val'),'0'); np.append(ni)
    p._p.get_or_add_pPr().append(np)
    return p

def figure(number,title,lead,after,height=45):
    p=para(lead,keep=True)
    p.paragraph_format.space_after=Pt(14)
    p=para(f'[МЕСТО ДЛЯ СКРИНШОТА {number}]',WD_ALIGN_PARAGRAPH.CENTER,True)
    p.paragraph_format.first_line_indent=Mm(0)
    p.paragraph_format.space_before=Pt(max(0,height*72/25.4-16))
    p.paragraph_format.space_after=Pt(0)
    p.paragraph_format.line_spacing=1
    p.paragraph_format.keep_together=True
    p=para(f'Рисунок {number} – {title}',WD_ALIGN_PARAGRAPH.CENTER,True)
    p.paragraph_format.first_line_indent=Mm(0); p.paragraph_format.space_after=Pt(14)
    para(after)

def table(number,title,headers,rows,widths=None):
    p=para(f'Таблица {number} – {title}',WD_ALIGN_PARAGRAPH.LEFT,True)
    p.paragraph_format.first_line_indent=Mm(0); p.paragraph_format.space_before=Pt(14)
    t=d.add_table(rows=1,cols=len(headers)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.autofit=False
    widths=widths or [165/len(headers)]*len(headers)
    for col,width in zip(t.columns,widths): col.width=Mm(width)
    for cell,width in zip(t.rows[0].cells,widths): cell.width=Mm(width)
    for cell,text in zip(t.rows[0].cells,headers): cell.text=str(text)
    for row in rows:
        cells=t.add_row().cells
        for c,width,text in zip(cells,widths,row): c.width=Mm(width); c.text=str(text)
    pr=t._tbl.tblPr
    for old in pr.findall(qn('w:tblBorders')): pr.remove(old)
    borders=OxmlElement('w:tblBorders')
    for side in ['top','left','bottom','right','insideH','insideV']:
        edge=OxmlElement('w:'+side); edge.set(qn('w:val'),'single'); edge.set(qn('w:sz'),'4'); edge.set(qn('w:color'),'000000'); borders.append(edge)
    pr.append(borders)
    margins=OxmlElement('w:tblCellMar')
    for name in ['top','bottom','left','right']:
        e=OxmlElement('w:'+name); e.set(qn('w:w'),'70'); e.set(qn('w:type'),'dxa'); margins.append(e)
    pr.append(margins)
    for i,row in enumerate(t.rows):
        trpr=row._tr.get_or_add_trPr(); trpr.append(OxmlElement('w:cantSplit'))
        if i==0: trpr.append(OxmlElement('w:tblHeader'))
        for cell in row.cells:
            cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            for p in cell.paragraphs:
                p.paragraph_format.first_line_indent=Mm(0); p.paragraph_format.space_before=Pt(0); p.paragraph_format.space_after=Pt(0)
                p.paragraph_format.line_spacing=1; p.paragraph_format.keep_with_next=(i<len(t.rows)-1)
                p.alignment=WD_ALIGN_PARAGRAPH.CENTER
                for r in p.runs: r.font.name='Times New Roman'; r.font.size=Pt(12 if i==0 else 14); r.bold=(i==0)
    p=para(); p.paragraph_format.space_after=Pt(14); p.paragraph_format.keep_with_next=True
    return t

