    p=para('[ЗАПОЛНИТЬ ПО РЕЗУЛЬТАТАМ ОПЫТА: '+text+']')
    for r in p.runs:
        sh=OxmlElement('w:highlight'); sh.set(qn('w:val'),'yellow'); r._r.get_or_add_rPr().append(sh)

