def native_cases(osname,sectionnum,kind,cases,base_figure):
    heading(f'{sectionnum}.'+('3 Два дочерних процесса' if kind=='b' else '4 Два дочерних потока'),2,page=True)
    para(('Lab-05b запускает два одинаковых дочерних процесса. ' if kind=='b' else 'Lab-05c запускает два одинаковых рабочих потока. ')+
         ('Для Windows процесс Lab-05c имеет класс Normal; относительные приоритеты задаются отдельно.' if osname=='Windows' and kind=='c' else
          'В каждом варианте используется одинаковая нагрузка, а число итераций сохраняется при первом завершении.'))
    for i,(mask,priority,args) in enumerate(cases):
        heading(f'{sectionnum}.'+('3' if kind=='b' else '4')+f'.{i+1} {mask} и приоритеты {priority}',3,page=i>0)
        para(f'Вариант {i+1}: {mask.lower().replace("cpu","CPU")}, приоритеты {priority}. Параметры командной строки для приоритетов: {args}. '+
             ('Исследуются разные процессы, поэтому необходимо сопоставить оба PID.' if kind=='b' else 'Оба исполнителя имеют один PID и разные TID.'))
        f1=f'{sectionnum}.{base_figure+i*2}'; f2=f'{sectionnum}.{base_figure+i*2+1}'
        if osname=='Windows':
            lead=f'Параметры '+('процессов' if kind=='b' else 'потоков')+f' в Process Explorer представлены на рисунке {f1}.'
            after='Сведения средства наблюдения сопоставляются с PID и TID, напечатанными программой. На одном CPU номера CPU обеих рабочих строк должны соответствовать разрешённому биту.'
        else:
            lead=f'Сведения ps и /proc о '+('процессах' if kind=='b' else 'потоках')+f' представлены на рисунке {f1}.'
            after='Поля NI и Cpus_allowed_list подтверждают фактически применённые nice и маску. Отрицательный nice должен быть установлен, а не только указан среди аргументов.'
        figure(f1,f'Приоритеты и маска Lab-05{kind}, вариант {i+1}',lead,after,40)
        figure(f2,f'Прогресс Lab-05{kind} при первом завершении, вариант {i+1}',
               f'Сохранённые значения счётчиков при первом завершении приведены на рисунке {f2}.',
               'Строка FIRST_FINISH указывает первого завершившего исполнителя, ITER1 и ITER2 — зарегистрированный прогресс. DELTA может быть равна нулю даже при различающихся моментах завершения.',40)
        pending('указать первого завершившегося исполнителя, ITER1, ITER2 и DELTA; объяснить результат с учётом числа CPU, блокировок и фактических приоритетов.')

native_cases('Windows',2,'b',cases_wb,3)
